-- Execute uma única vez no schema Oracle utilizado pela API AlertaCidadao.
-- Script idempotente: cria a tabela e os índices somente quando ainda não existem.

DECLARE
    V_COUNT INTEGER;
BEGIN
    SELECT COUNT(*) INTO V_COUNT
      FROM USER_TABLES
     WHERE TABLE_NAME = 'OCORRENCIA';

    IF V_COUNT = 0 THEN
        EXECUTE IMMEDIATE '
            CREATE TABLE "OCORRENCIA" (
                "ID_OCORRENCIA" NUMBER(20,0) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
                "ID_USUARIO" NUMBER(20,0),
                "ID_PONTO" NUMBER(20,0),
                "TIPO" NVARCHAR2(30) NOT NULL,
                "TITULO" NVARCHAR2(120) NOT NULL,
                "DESCRICAO" NVARCHAR2(1000) NOT NULL,
                "LOGRADOURO" NVARCHAR2(180),
                "BAIRRO" NVARCHAR2(100),
                "CIDADE" NVARCHAR2(100),
                "UF" CHAR(2),
                "LATITUDE" NUMBER(9,6),
                "LONGITUDE" NUMBER(9,6),
                "STATUS" NVARCHAR2(20) DEFAULT ''ABERTA'' NOT NULL,
                "DATA_CRIACAO" TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
                "DATA_ATUALIZACAO" TIMESTAMP WITH TIME ZONE,
                CONSTRAINT "PK_OCORRENCIA" PRIMARY KEY ("ID_OCORRENCIA"),
                CONSTRAINT "FK_OCORRENCIA_USUARIO" FOREIGN KEY ("ID_USUARIO") REFERENCES "USUARIO" ("ID_USUARIO"),
                CONSTRAINT "FK_OCORRENCIA_PONTO" FOREIGN KEY ("ID_PONTO") REFERENCES "PONTO_MONITORAMENTO" ("ID_PONTO")
            )';
    END IF;

    SELECT COUNT(*) INTO V_COUNT
      FROM USER_INDEXES
     WHERE INDEX_NAME = 'IX_OCORRENCIA_USUARIO_DATA';
    IF V_COUNT = 0 THEN
        EXECUTE IMMEDIATE 'CREATE INDEX "IX_OCORRENCIA_USUARIO_DATA" ON "OCORRENCIA" ("ID_USUARIO", "DATA_CRIACAO")';
    END IF;

    SELECT COUNT(*) INTO V_COUNT
      FROM USER_INDEXES
     WHERE INDEX_NAME = 'IX_OCORRENCIA_PONTO';
    IF V_COUNT = 0 THEN
        EXECUTE IMMEDIATE 'CREATE INDEX "IX_OCORRENCIA_PONTO" ON "OCORRENCIA" ("ID_PONTO")';
    END IF;
END;
/

-- Registra a migration para manter o histórico do EF Core alinhado com o SQL manual.
-- Se a tabela de histórico não existir neste schema, a criação por este script ainda é válida;
-- nesse caso, não execute dotnet ef database update sem ajustar o histórico primeiro.
DECLARE
    V_COUNT INTEGER;
BEGIN
    SELECT COUNT(*) INTO V_COUNT
      FROM USER_TABLES
     WHERE TABLE_NAME = '__EFMigrationsHistory';

    IF V_COUNT > 0 THEN
        EXECUTE IMMEDIATE
            'SELECT COUNT(*) FROM "__EFMigrationsHistory" WHERE "MigrationId" = ''20261117140000_AddOcorrencia''' 
            INTO V_COUNT;

        IF V_COUNT = 0 THEN
            EXECUTE IMMEDIATE
                'INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion") VALUES (''20261117140000_AddOcorrencia'', ''9.0.0'')';
        END IF;
    END IF;
END;
/
COMMIT;

-- Conferência rápida:
SELECT TABLE_NAME FROM USER_TABLES WHERE TABLE_NAME = 'OCORRENCIA';
SELECT CONSTRAINT_NAME, CONSTRAINT_TYPE FROM USER_CONSTRAINTS WHERE TABLE_NAME = 'OCORRENCIA';
